begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into public.departments(id,name) values('27000000-0000-4000-8000-000000000001','Security fixtures');
insert into auth.users(id) select ('27000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid from generate_series(11,16) i;
insert into public.profiles(id,department_id,display_name,role)
select ('27000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'27000000-0000-4000-8000-000000000001','Fixture '||i,
 case when i in (11,12) then 'administrador'::public.application_role when i in (13,14) then 'gestor'::public.application_role else 'membro'::public.application_role end
from generate_series(11,16) i;
insert into vittahub_private.master_account(user_id) values('27000000-0000-4000-8000-000000000011');
insert into public.boards(id,department_id,title,created_by) values('27000000-0000-4000-8000-000000000020','27000000-0000-4000-8000-000000000001','Board','27000000-0000-4000-8000-000000000015');
insert into public.board_memberships(board_id,user_id,added_by) select '27000000-0000-4000-8000-000000000020',id,'27000000-0000-4000-8000-000000000011' from public.profiles where id::text like '27000000-%' and id<>'27000000-0000-4000-8000-000000000015';
insert into public.board_columns(id,board_id,title,position) values('27000000-0000-4000-8000-000000000021','27000000-0000-4000-8000-000000000020','Column',0);
insert into public.tasks(id,board_id,column_id,title,created_by,assignee_id,due_at,is_private) values('27000000-0000-4000-8000-000000000022','27000000-0000-4000-8000-000000000020','27000000-0000-4000-8000-000000000021','Task','27000000-0000-4000-8000-000000000015','27000000-0000-4000-8000-000000000015',now(),false);
insert into public.conversations(id,kind) values('27000000-0000-4000-8000-000000000023','individual');
insert into public.conversation_participants(conversation_id,user_id) values('27000000-0000-4000-8000-000000000023','27000000-0000-4000-8000-000000000015');
insert into public.messages(conversation_id,author_id,content) values('27000000-0000-4000-8000-000000000023','27000000-0000-4000-8000-000000000015','Preserved');
insert into auth.sessions(id,user_id,created_at,updated_at) values('27000000-0000-4000-8000-000000000029','27000000-0000-4000-8000-000000000015',clock_timestamp(),clock_timestamp());

set local role authenticated;
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000012',true);
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000015','deactivate')$$,'42501',null::text,'ordinary admin has no activation power');
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000011',true);
select is((public.employee_security_context()->>'is_master')::boolean,true,'master identified in database');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000015','grant')$$,'42501',null::text,'member cannot receive delegation');
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000013','grant')$$,'master delegates to manager');
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000014','grant')$$,'second delegate');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000011','deactivate')$$,'42501',null::text,'master cannot deactivate self');
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000013',true);
select is(vittahub_private.is_system_admin(),false,'delegation does not grant global administration');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000012','grant')$$,'42501',null::text,'delegate cannot delegate');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000012','deactivate')$$,'42501',null::text,'delegate cannot change admin');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000014','deactivate')$$,'42501',null::text,'delegate cannot change delegate');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000011','deactivate')$$,'42501',null::text,'delegate cannot change master');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000013','deactivate')$$,'42501',null::text,'delegate cannot change self');
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000015','deactivate')$$,'delegate deactivates member');
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000015',true);
select set_config('request.jwt.claims','{"session_id":"27000000-0000-4000-8000-000000000029","iat":9999999999}',true);
select is(public.employee_access_status(),false,'inactive old token denied');
select is((select count(*)::int from public.profiles),0,'profile hidden');
select is((select count(*)::int from public.boards),0,'board hidden');
select is((select count(*)::int from public.tasks),0,'tasks hidden');
select is((select count(*)::int from public.messages),0,'messages hidden');
select is((select count(*)::int from public.board_memberships),0,'memberships hidden');
select throws_ok($$select public.accept_task('27000000-0000-4000-8000-000000000022')$$,'42501',null::text,'legacy transition denied');
select throws_ok($$select public.send_message('27000000-0000-4000-8000-000000000023','Denied')$$,'42501',null::text,'legacy chat write denied');
select throws_ok($$select public.add_task_comment('27000000-0000-4000-8000-000000000022','Denied')$$,'42501',null::text,'legacy comment denied');
select throws_ok($$select * from public.list_board_assignees('27000000-0000-4000-8000-000000000020')$$,'42501',null::text,'legacy read RPC denied');
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000011',true);
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000015','activate')$$,'master reactivates');
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000015',true);
select is(public.employee_access_status(),false,'reactivation rejects existing Auth session even with refreshed JWT iat');
reset role;
insert into auth.sessions(id,user_id,created_at,updated_at) values('27000000-0000-4000-8000-000000000030','27000000-0000-4000-8000-000000000015',clock_timestamp()+interval '1 second',clock_timestamp());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"27000000-0000-4000-8000-000000000015","session_id":"27000000-0000-4000-8000-000000000030"}',true);
select is(public.employee_access_status(),true,'new Auth session accepted after activation');
select lives_ok($$select public.accept_task('27000000-0000-4000-8000-000000000022')$$,'active legacy transition preserved');
reset role;
select is((select count(*)::int from public.messages where content='Preserved'),1,'messages preserved');
select is((select assignee_id::text from public.tasks where id='27000000-0000-4000-8000-000000000022'),'27000000-0000-4000-8000-000000000015','assignee preserved');
select is((select count(*)::int from vittahub_private.employee_security_events where action in ('activated','deactivated')),2,'atomic activity audit');
select is((select count(*)::int from vittahub_private.employee_security_events where action='delegation_granted'),2,'grant audit; denied requests added nothing');
select throws_ok($$update public.profiles set role='gestor' where id='27000000-0000-4000-8000-000000000011'$$,'42501',null::text,'master cannot be demoted');
update public.profiles set role='membro' where id='27000000-0000-4000-8000-000000000013';
update public.profiles set role='gestor' where id='27000000-0000-4000-8000-000000000013';
select ok((select revoked_at is not null from vittahub_private.employee_delegations where user_id='27000000-0000-4000-8000-000000000013'),'lost eligibility persistently revokes');
select ok(not has_table_privilege('authenticated','vittahub_private.master_account','UPDATE'),'no direct master mutation');
select ok(not has_table_privilege('authenticated','vittahub_private.employee_security_events','INSERT'),'no forged audit');
select ok(not has_function_privilege('authenticated','vittahub_private.impl_send_message(uuid,text)','EXECUTE'),'cannot bypass wrapper');
-- Audit failure must roll back both the state and session cutoff.
create function pg_temp.fail_security_event() returns trigger language plpgsql as $$ begin raise exception 'forced audit failure'; end $$;
create trigger test_security_atomicity before insert on vittahub_private.employee_security_events for each row execute function pg_temp.fail_security_event();
set local role authenticated;
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000011',true);
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000016','deactivate')$$,'P0001','forced audit failure','audit failure aborts deactivation');
reset role;
select ok((select is_active from public.profiles where id='27000000-0000-4000-8000-000000000016'),'failed audit preserves state');
select is((select count(*)::int from vittahub_private.employee_session_cutoffs where user_id='27000000-0000-4000-8000-000000000016'),0,'failed audit preserves session');
drop trigger test_security_atomicity on vittahub_private.employee_security_events;
-- Only transient fixture changes, rolled back with the test.
update auth.users set banned_until=clock_timestamp()+interval '1 day' where id='27000000-0000-4000-8000-000000000011';
set local role authenticated;
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000014',true);
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000016','deactivate')$$,'42501',null::text,'banned master blocks delegated operations');
reset role;
update auth.users set banned_until=null,deleted_at=clock_timestamp() where id='27000000-0000-4000-8000-000000000011';
select is(vittahub_private.valid_master(),false,'soft-deleted Auth master is invalid');
update auth.users set deleted_at=null where id='27000000-0000-4000-8000-000000000011';
delete from vittahub_private.master_account;
set local role authenticated;
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000014',true);
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000016','deactivate')$$,'42501',null::text,'no master blocks delegated operations');
reset role;
select throws_ok($$insert into vittahub_private.master_account(user_id) values('27000000-0000-4000-8000-000000000016')$$,'42501',null::text,'master must be administrator');
insert into vittahub_private.master_account(user_id) values('27000000-0000-4000-8000-000000000011');
select throws_ok($$insert into vittahub_private.master_account(user_id) values('27000000-0000-4000-8000-000000000012')$$,'23505',null::text,'only one master');
set local role authenticated;
select set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000011',true);
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000012','grant')$$,'active admin eligible for delegation');
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000012','revoke')$$,'master revokes immediately');
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000014','deactivate')$$,'master deactivates delegate');
select throws_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000014','grant')$$,'42501',null::text,'inactive manager cannot receive delegation');
select lives_ok($$select public.change_employee_security('27000000-0000-4000-8000-000000000014','activate')$$,'master reactivates former delegate');
reset role;
select ok((select revoked_at is not null from vittahub_private.employee_delegations where user_id='27000000-0000-4000-8000-000000000014'),'reactivation never restores delegation');
select * from finish();
rollback;
